"""Metadata schema, validation, and Chroma ``where``-clause generation.

The system treats metadata as a first-class citizen:

* **Ingestion**  - every chunk must carry validated metadata so that
  filtering is reliable (no typos in categories, no wrong types).
* **Filtering**  - user filters are expressed with a small, typed DSL and
  compiled to Chroma's native ``where`` clause (pre-filtering happens
  *inside* the vector store, before similarity search).
* **Ranking**    - metadata values are consumed by :mod:`rag.ranking` to
  boost documents (recency, priority, source trust, tag overlap).
"""

from __future__ import annotations

from datetime import date, datetime
from typing import Any, Dict, List

# ---------------------------------------------------------------------------
# Schema
# ---------------------------------------------------------------------------
ALLOWED_CATEGORIES = ["technology", "finance", "health", "operations"]
ALLOWED_SOURCES = ["docs", "report", "email", "wiki", "press"]
SOURCE_TRUST = {  # used by the ranker as a source-quality prior
    "docs": 1.0,
    "report": 0.9,
    "wiki": 0.75,
    "press": 0.6,
    "email": 0.45,
}
MAX_PRIORITY = 5

METADATA_SCHEMA: Dict[str, Dict[str, Any]] = {
    "category": {"type": "str", "allowed": ALLOWED_CATEGORIES},
    "source": {"type": "str", "allowed": ALLOWED_SOURCES},
    "author": {"type": "str"},
    "date": {"type": "date"},          # ISO-8601 date string, e.g. 2024-06-01
    "priority": {"type": "int", "min": 1, "max": MAX_PRIORITY},
    "confidence": {"type": "float", "min": 0.0, "max": 1.0},
    "tags": {"type": "list", "item_type": "str"},
    "doc_id": {"type": "str"},
}

# Operators Chroma accepts on scalar/string/list metadata.
_SCALAR_OPS = {"$eq", "$ne", "$gt", "$gte", "$lt", "$lte", "$in", "$nin"}
_LIST_OPS = {"$contains", "$not_contains"}
_LOGICAL_OPS = {"$and", "$or"}


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------
def _parse_date(value: str) -> date:
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid date {value!r}; expected YYYY-MM-DD") from None


def validate_metadata(metadata: Dict[str, Any]) -> Dict[str, Any]:
    """Validate a metadata dict against the schema.  Raises ValueError."""
    if not isinstance(metadata, dict):
        raise ValueError("metadata must be a dict")
    cleaned: Dict[str, Any] = {}
    for key, value in metadata.items():
        if key not in METADATA_SCHEMA:
            raise ValueError(f"Unknown metadata field {key!r}")
        spec = METADATA_SCHEMA[key]
        kind = spec["type"]

        if kind == "str":
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"{key} must be a non-empty string")
            if "allowed" in spec and value not in spec["allowed"]:
                raise ValueError(
                    f"{key}={value!r} not allowed; choose from {spec['allowed']}"
                )
        elif kind == "date":
            if not isinstance(value, str):
                raise ValueError(f"{key} must be an ISO date string")
            _parse_date(value)
        elif kind == "int":
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValueError(f"{key} must be an int")
            if value < spec.get("min", -(2**31)) or value > spec.get("max", 2**31):
                raise ValueError(f"{key} out of range [{spec.get('min')}, {spec.get('max')}]")
        elif kind == "float":
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError(f"{key} must be a number")
            value = float(value)
            if value < spec.get("min", float("-inf")) or value > spec.get("max", float("inf")):
                raise ValueError(f"{key} out of range [{spec.get('min')}, {spec.get('max')}]")
        elif kind == "list":
            if not isinstance(value, list) or not all(
                isinstance(item, spec.get("item_type", str)) for item in value
            ):
                raise ValueError(f"{key} must be a list of {spec.get('item_type')}")
        cleaned[key] = value
    return cleaned


# ---------------------------------------------------------------------------
# Filter DSL -> Chroma where clause
# ---------------------------------------------------------------------------
def build_where_clause(filters: Dict[str, Any]) -> Dict[str, Any]:
    """Compile the filter DSL into a Chroma ``where`` clause.

    Supported forms (all keys must exist in :data:`METADATA_SCHEMA`)::

        {"category": "technology"}                    # equality
        {"priority": {"$gte": 4}}                     # operator on scalar
        {"date": {"$gte": "2024-01-01"}}              # ISO dates compare lexically
        {"tags": {"$contains": "rag"}}                # list membership
        {"tags": {"$in": ["rag", "llm"]}}
        {"$or": [{"source": "docs"}, {"source": "report"}]}

    Returns an empty dict when no filter is given (Chroma ignores it).
    """
    if not filters:
        return {}

    clauses = []
    for key, value in filters.items():
        if key in _LOGICAL_OPS:
            if not isinstance(value, list) or not value:
                raise ValueError(f"{key} expects a non-empty list of sub-filters")
            clauses.append({key: [build_where_clause(sub) for sub in value]})
            continue

        if key not in METADATA_SCHEMA:
            raise ValueError(f"Unknown filter field {key!r}")
        spec = METADATA_SCHEMA[key]
        kind = spec["type"]

        if isinstance(value, dict):
            for op, operand in value.items():
                if op not in _SCALAR_OPS and op not in _LIST_OPS:
                    raise ValueError(f"Unsupported operator {op!r} for field {key!r}")
                if op in _LIST_OPS and kind != "list":
                    raise ValueError(f"{op} is only valid for list fields, not {key!r}")
                if op in _SCALAR_OPS and kind == "list":
                    raise ValueError(f"{op} is not valid for list field {key!r}")
            clauses.append({key: value})
        elif kind == "str":
            if value not in spec.get("allowed", [value]):
                raise ValueError(
                    f"Filter {key}={value!r} not allowed; choose from {spec['allowed']}"
                )
            clauses.append({key: value})  # Chroma equality shorthand
        elif kind in ("int", "float"):
            clauses.append({key: {"$eq": value}})
        elif kind == "date":
            _parse_date(value)
            clauses.append({key: {"$eq": value}})
        elif kind == "list":
            raise ValueError(f"List field {key!r} needs an operator, e.g. {{'$contains': ...}}")
        else:  # pragma: no cover - schema is closed
            raise ValueError(f"Cannot filter on {key!r}")

    if len(clauses) == 1:
        return clauses[0]
    return {"$and": clauses}


def describe_filters(filters: Dict[str, Any]) -> str:
    """Human-readable summary of the active metadata filters."""
    if not filters:
        return "none"
    parts = []
    for key, value in filters.items():
        if isinstance(value, dict):
            ops = ", ".join(f"{op} {operand}" for op, operand in value.items())
            parts.append(f"{key} {ops}")
        else:
            parts.append(f"{key} = {value}")
    return "; ".join(parts)

